  IF EXISTS(SELECT FROM jsonb_array_elements(binding.refs_) r WHERE NOT row_map ? (r->>'contribution_id')) THEN
   RAISE EXCEPTION 'retained contribution unavailable' USING ERRCODE='23514';END IF;
