 IF a->>'space'<>'native' OR a->>'precision'<>'exact' OR a->'pin' IS DISTINCT FROM v->'pin' THEN RAISE EXCEPTION 'contribution lacks exact native bridge' USING ERRCODE='23514';END IF;
