 (item->>'item_ref')||CASE WHEN item->>'cell_index' IS NULL THEN '' ELSE '/data/table_cells/'||(item->>'cell_index') END=a->>'pointer';
 start_:=(piece->>'start')::integer+(a->>'start')::integer;end_:=(piece->>'start')::integer+(a->>'end')::integer;
