  ELSIF NOT COALESCE(kind_='exception' AND left(cue->>'variant',8)='nominal_'
   AND marker->>'dependency'='prep' AND marker->'head'=to_jsonb(origin),false) THEN RETURN false;
  END IF;
 ELSIF kind_ IN ('modality','negation') THEN
