INSERT INTO data.assessment(release_id,realization_id,"assessment_id","operation_id","operation_version","outcome","fact_id","occurrence_id","confidence","reason","uncertainty","counterpart_fact_id","counterpart_occurrence_id","context_value_id","comparison_tier","semantic_reason") SELECT r,z,"assessment_id","operation_id","operation_version","outcome","fact_id","occurrence_id","confidence","reason","uncertainty","counterpart_fact_id","counterpart_occurrence_id","context_value_id","comparison_tier","semantic_reason" FROM pg_temp.sp_assessment ON CONFLICT DO NOTHING; IF EXISTS(SELECT "assessment_id","operation_id","operation_version","outcome","fact_id","occurrence_id","confidence","reason","uncertainty","counterpart_fact_id","counterpart_occurrence_id","context_value_id","comparison_tier","semantic_reason" FROM pg_temp.sp_assessment EXCEPT SELECT "assessment_id","operation_id","operation_version","outcome","fact_id","occurrence_id","confidence","reason","uncertainty","counterpart_fact_id","counterpart_occurrence_id","context_value_id","comparison_tier","semantic_reason" FROM data.assessment WHERE release_id=r AND realization_id=z) THEN RAISE EXCEPTION 'conflicting existing assessment' USING ERRCODE='23505'; END IF;
