CREATE OR REPLACE FUNCTION data.publish_contract_batch(r text,z text,b text,p_content bytea) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $transport$

DECLARE actual bytea; old data.batch%ROWTYPE; rev bigint; f record; application record; expected text;
BEGIN
 PERFORM sem.require_execution_operation(r,'publish');
 IF current_setting('transaction_isolation')<>'serializable' THEN RAISE EXCEPTION 'publication requires SERIALIZABLE'; END IF;
 IF NOT EXISTS(SELECT FROM pg_catalog.pg_class stage_catalog_relation WHERE stage_catalog_relation.relnamespace=pg_my_temp_schema() AND stage_catalog_relation.relname='sp_alternative_group' AND stage_catalog_relation.relkind='r' AND stage_catalog_relation.relpersistence='t' AND stage_catalog_relation.relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user) AND (SELECT array_agg(stage_catalog_attribute.attname||':'||format_type(stage_catalog_attribute.atttypid,stage_catalog_attribute.atttypmod) ORDER BY stage_catalog_attribute.attnum) FROM pg_catalog.pg_attribute stage_catalog_attribute WHERE stage_catalog_attribute.attrelid=stage_catalog_relation.oid AND stage_catalog_attribute.attnum>0 AND NOT stage_catalog_attribute.attisdropped)=ARRAY['group_id:text','reason:text','operation_id:text','operation_version:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_alternative_group'; END IF;
IF NOT EXISTS(SELECT FROM pg_catalog.pg_class stage_catalog_relation WHERE stage_catalog_relation.relnamespace=pg_my_temp_schema() AND stage_catalog_relation.relname='sp_coverage' AND stage_catalog_relation.relkind='r' AND stage_catalog_relation.relpersistence='t' AND stage_catalog_relation.relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user) AND (SELECT array_agg(stage_catalog_attribute.attname||':'||format_type(stage_catalog_attribute.atttypid,stage_catalog_attribute.atttypmod) ORDER BY stage_catalog_attribute.attnum) FROM pg_catalog.pg_attribute stage_catalog_attribute WHERE stage_catalog_attribute.attrelid=stage_catalog_relation.oid AND stage_catalog_attribute.attnum>0 AND NOT stage_catalog_attribute.attisdropped)=ARRAY['coverage_id:text','family:text','scope:text','outcome:text','reason:text','source_outcome:text','required_capability:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_coverage'; END IF;
IF NOT EXISTS(SELECT FROM pg_catalog.pg_class stage_catalog_relation WHERE stage_catalog_relation.relnamespace=pg_my_temp_schema() AND stage_catalog_relation.relname='sp_entity' AND stage_catalog_relation.relkind='r' AND stage_catalog_relation.relpersistence='t' AND stage_catalog_relation.relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user) AND (SELECT array_agg(stage_catalog_attribute.attname||':'||format_type(stage_catalog_attribute.atttypid,stage_catalog_attribute.atttypmod) ORDER BY stage_catalog_attribute.attnum) FROM pg_catalog.pg_attribute stage_catalog_attribute WHERE stage_catalog_attribute.attrelid=stage_catalog_relation.oid AND stage_catalog_attribute.attnum>0 AND NOT stage_catalog_attribute.attisdropped)=ARRAY['entity_id:text']) THEN RAISE EXCEPTION 'untrusted staging relation sp_entity'; END IF;
