 FROM pg_temp.sp_occurrence_establishment) OR EXISTS(SELECT FROM pg_temp.sp_evidence_source) OR EXISTS(SELECT FROM pg_temp.sp_assessment) OR EXISTS(SELECT FROM pg_temp.sp_entity_input) OR EXISTS(SELECT FROM pg_temp.sp_fact_input) OR EXISTS(SELECT FROM pg_temp.sp_alternative_group) OR EXISTS(SELECT FROM pg_temp.sp_alternative_member) THEN
